import {initCompanion} from './companion.js';
let companion=null;
import {normalizeSearch, parseAmount, parseSearchIntent, matchesQuery} from './search.js';
import {rankRows} from './relevance.js';
const $=s=>document.querySelector(s), fa=n=>Number(n).toLocaleString('fa-IR'), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=n=>`<svg class="icon" aria-hidden="true"><use href="#i-${n}"></use></svg>`;
const price=n=>n?`${fa(n)} <small>تومان</small>`:'قیمت نامشخص';
const norm=normalizeSearch;
const storage={get(k,d){try{return JSON.parse(localStorage.getItem(k))??d}catch{return d}},set(k,v){try{localStorage.setItem(k,JSON.stringify(v))}catch{toast('ذخیره در این مرورگر ممکن نیست.')}}};
const state={products:[],shown:16,compare:[],point:storage.get('point',{lat:35.7007,lon:51.4091,label:'تهران، مرکز شهر'}),plan:storage.get('plan',[]),notes:storage.get('notes',{}),excluded:new Set(),selected:null,query:'',seq:0};
const cache=new Map();let shops={},meta={},allIndex=null,indexPromise,guide={category:'کفش',use:'روزمره',budget:''};
async function json(url){if(!cache.has(url))cache.set(url,fetch(url).then(async r=>{if(!r.ok)throw Error('خطا در دریافت اطلاعات');const payload=await r.json();const bytes=Uint8Array.from(atob(payload.gzip),c=>c.charCodeAt(0));const stream=new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'));return JSON.parse(await new Response(stream).text())}).catch(e=>{cache.delete(url);throw e}));return cache.get(url)}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4200)}
function modal(html){$('#modalBody').innerHTML=html; if(!$('#modal').open)$('#modal').showModal()}
function close(){$('#modal').close()}
$('#closeModal').onclick=close;$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))close()});
function img(p,cls=''){const fallback=`<span class="placeholder">${icon('picture')}<small>تصویر در دسترس نیست</small></span>`;return p.image&&/^https:\/\//.test(p.image)?`<img class="${esc(cls)}" src="${esc(p.image)}" alt="${esc(p.title)}" loading="lazy" referrerpolicy="no-referrer" onerror="this.outerHTML=${esc(JSON.stringify(fallback))}">`:fallback}
function distance(s){if(!s||!Number.isFinite(s.lat)||!Number.isFinite(s.lon))return null;let rad=x=>x*Math.PI/180,a=rad(s.lat-state.point.lat),b=rad(s.lon-state.point.lon);return 6371*2*Math.asin(Math.sqrt(Math.sin(a/2)**2+Math.cos(rad(s.lat))*Math.cos(rad(state.point.lat))*Math.sin(b/2)**2))}
function visit(){const v=$('#visitTime').value;return v?new Date(v+'+03:30'):new Date()}
function hours(s){const d=visit(),parts=Object.fromEntries(new Intl.DateTimeFormat('en-US',{timeZone:'Asia/Tehran',weekday:'short',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(d).map(x=>[x.type,x.value]));const h=s?.weekly_hours?.[parts.weekday.toLowerCase()];if(!h||!h.status||h.status==='unknown')return {open:null,text:'ساعت کاری نامشخص'};if(h.status==='closed')return {open:false,text:'طبق برنامه تعطیل است'};const mins=Number(parts.hour)*60+Number(parts.minute),toM=t=>Number(t.slice(0,2))*60+Number(t.slice(3,5));const shifts=(h.shifts||[]).filter(x=>x.start_time!==x.end_time);if(!shifts.length)return {open:null,text:'ساعت کاری نامشخص'};const isOpen=shifts.some(x=>{let a=toM(x.start_time),b=toM(x.end_time);return b>a?mins>=a&&mins<b:mins>=a||mins<b});return {open:isOpen,text:(isOpen?'طبق برنامه باز است':'طبق برنامه بسته است')+' · '+shifts.map(x=>x.start_time.slice(0,5)+' تا '+x.end_time.slice(0,5)).join('، ')} }
function credit(s,o){return (s.payment_options||[]).filter(x=>x.channel==='in_person'&&(!x.min_price_toman||o.price>=x.min_price_toman)&&(!x.max_price_toman||o.price<=x.max_price_toman)&&(!x.category_names?.length||x.category_names.includes(o.category||state.selected?.category)))}
function qualifying(p){const matches=p.offers.filter(o=>{const s=shops[o.shop];if(!s||state.excluded.has(o.shop))return false;const b=parseAmount($('#budget').value),d=distance(s),r=+$('#radius').value;if(b&&(!o.price||o.price>b))return false;if(r<100&&(d===null||d>r))return false;if($('#credit').checked&&!credit(s,{...o,category:p.category}).length)return false;if($('#openOnly').checked&&hours(s).open!==true)return false;return true});const grouped=new Map();for(const o of matches){const old=grouped.get(o.shop);if(!old||(o.price||Infinity)<(old.price||Infinity))grouped.set(o.shop,o)}return [...grouped.values()]}
function productCard(p){const offers=qualifying(p),min=Math.min(...offers.map(x=>x.price).filter(x=>x>0));return `<article class="product">${companion?.favoriteButton(p)||''}<button class="image-btn" data-product="${p.id}" aria-label="مشاهده ${esc(p.title)}">${img(p)}</button><div class="card-body"><span class="category">${esc(p.category)}</span><button class="product-title" data-product="${p.id}">${esc(p.title)}</button><div class="price">${price(isFinite(min)?min:null)}</div><span class="sellers">در ${fa(offers.length)} فروشگاه · قیمت ثبت‌شده</span><div class="card-foot"><button data-product="${p.id}">فروشگاه‌ها ${icon('arrow')}</button><label><input type="checkbox" data-compare="${p.id}" aria-label="افزودن ${esc(p.title)} به مقایسه" ${state.compare.some(x=>x.id===p.id)?'checked':''}> مقایسه</label></div></div></article>`}
function render(){let ps=state.products.filter(p=>qualifying(p).length);const sort=$('#productSort').value;if(sort==='cheap')ps.sort((a,b)=>(Math.min(...qualifying(a).map(o=>o.price||Infinity)))-(Math.min(...qualifying(b).map(o=>o.price||Infinity))));if(sort==='sellers')ps.sort((a,b)=>qualifying(b).length-qualifying(a).length);$('#products').innerHTML=ps.length?ps.slice(0,state.shown).map(productCard).join(''):`<div class="empty"><b>گزینه‌ای با این شرایط پیدا نشد</b><p>بودجه یا محدوده را بیشتر کن، یا فیلتر اعتبار و ساعت را بردار.</p><button data-reset>پاک کردن فیلترها</button></div>`;$('#more').hidden=ps.length<=state.shown;$('#resultCount').textContent=`${fa(ps.length)} محصول مطابق شرایط شما`;
$('#activeFilters').textContent=[$('#credit').checked?'خرید اعتباری حضوری':'',$('#openOnly').checked?'باز در زمان مراجعه':'',parseAmount($('#budget').value)?'تا '+fa($('#budget').value)+' تومان':'',+$('#radius').value<100?'شعاع '+fa($('#radius').value)+' کیلومتر':''].filter(Boolean).join(' · ');companion?.refresh()}
async function loadIndex(){if(!indexPromise)indexPromise=Promise.all(Array.from({length:8},(_,i)=>json(`data/index${i}.json`))).then(x=>{allIndex=x.flat();return allIndex}).catch(e=>{indexPromise=null;throw e});return indexPromise}
async function hydrate(row){return (await json(`data/p${row[3]}.json`))[row[0]]}
async function search(q){const intent=parseSearchIntent(q);q=intent.query;if(intent.budget)$('#budget').value=intent.budget;$('#query').value=q;const seq=++state.seq;state.query=q;state.shown=16;showCatalog();$('#resultTitle').textContent=q?`نتایج جستجو برای «${q}»`:'محصولات پیشنهادی';$('#status').textContent='در حال پیدا کردن محصولات…';$('#products').innerHTML=Array(8).fill('<div class="skeleton"></div>').join('');try{let idx=await loadIndex();if(seq!==state.seq)return;const terms=norm(q).split(' ').filter(Boolean);let found=rankRows(idx.filter(x=>matchesQuery(x,q)),q);let b=parseAmount($('#budget').value);if(b)found=found.filter(x=>x[4]&&x[4]<=b);if($('#productSort').value==='cheap')found.sort((a,b)=>(a[4]||Infinity)-(b[4]||Infinity));const limited=found.slice(0,160);const items=await Promise.all(limited.map(hydrate));if(seq!==state.seq)return;state.products=items;render();companion?.searched(q);$('#status').textContent=`${fa(found.length)} نتیجه پیدا شد؛ ${fa(items.length)} گزینهٔ نخست برای مقایسه آماده است.`;if(found.length>160)$('#status').textContent+=' برای نتیجهٔ دقیق‌تر، برند یا مدل را وارد کن.'}catch(e){if(seq===state.seq){$('#status').textContent='دریافت داده‌ها ناموفق بود. اتصال را بررسی و دوباره جستجو کن.';$('#products').innerHTML='<div class="empty">داده‌ها بارگیری نشدند.<button id="retrySearch">تلاش دوباره</button></div>';$('#retrySearch').onclick=()=>search(q)}}}
function showCatalog(){companion?.catalog();$('#catalog').hidden=false;$('#detail').hidden=true;$('#step2').classList.remove('active');$('#step3').classList.remove('active')}
async function openProduct(id){let p=state.products.find(x=>x.id===id)||state.compare.find(x=>x.id===id);try{if(!p){let idx=await loadIndex(),row=idx.find(x=>x[0]===id);if(!row)throw Error();p=await hydrate(row)}state.selected=p;companion?.viewed(p);$('#catalog').hidden=true;$('#detail').hidden=false;$('#step2').classList.add('active');renderDetail();$('#detail').scrollIntoView({behavior:'smooth',block:'start'})}catch{toast('دریافت محصول ممکن نشد؛ دوباره امتحان کن.')}}
function offerAge(o){let d=new Date(o.updated);return isNaN(d)?'زمان تغییر قیمت نامشخص':d.toLocaleDateString('fa-IR',{timeZone:'Asia/Tehran'})}
function ranked(p){let os=qualifying(p).map(o=>({...o,s:shops[o.shop]})),sort=$('#shopSort')?.value||'balanced',prices=os.map(o=>o.price).filter(x=>x>0),min=Math.min(...prices);os.forEach(o=>{let dist=distance(o.s),h=hours(o.s);o.score=(o.price&&isFinite(min)?o.price/min:4)*.45+(dist===null?2:Math.min(dist/10,3))*.35+(h.open===true?0:h.open===false?1:.5)*.2});if(sort==='price')os.sort((a,b)=>(a.price||Infinity)-(b.price||Infinity));else if(sort==='distance')os.sort((a,b)=>(distance(a.s)??Infinity)-(distance(b.s)??Infinity));else os.sort((a,b)=>a.score-b.score);return os}
function shopCard(o,i){let s=o.s,d=distance(s),h=hours(s),c=credit(s,o),note=state.notes[state.selected.id+o.shop];return `<article class="shop-card"><div><span class="reason">${i===0?'پیشنهاد اول در ترتیب فعلی · ':''}${d===null?'فاصله نامشخص':fa(d.toFixed(1))+' کیلومتر فاصله مستقیم'}</span><h3>${esc(s.name)} <span class="badge gray">نام دیتاست</span></h3><p class="small">گزینهٔ فروشنده: ${esc(o.title||state.selected.title)}</p><p>⌖ ${esc(s.address||s.location_label||'آدرس نامشخص')}</p><span class="badge ${h.open===true?'green':'gray'}">${esc(h.text)}</span><div class="chips">${c.map(x=>`<span class="chip">${esc(x.provider_name)} · پذیرش حضوری ثبت‌شده</span>`).join('')}${!c.length?'<span class="chip">اعتبار حضوری تأیید نشده</span>':''}</div><div class="shop-actions"><button data-verify="${o.shop}">◷ پیگیری قیمت و موجودی</button><a target="_blank" rel="noopener" href="https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(s.lat&&s.lon?s.lat+','+s.lon:s.address||'تهران')}">⌖ مسیریابی</a><button data-address="${o.shop}">آدرس داخل پاساژ</button><button data-save="${o.shop}">♡ ذخیره در برنامه</button><button data-fail="${o.shop}">بسته بود / پاسخ نداد</button></div>${note?`<p class="small">یادداشت شخصی شما: ${esc(note.text)} · ${esc(new Date(note.at).toLocaleString('fa-IR'))}</p>`:''}</div><div class="shop-meta"><div class="shop-price">${price(o.price)}</div><p>قیمت ثبت‌شده در دیتاست</p><span class="badge">موجودی تأیید نشده</span><p class="small">آخرین تغییر قیمت: ${esc(offerAge(o))}</p><p class="small">باز بودن بر اساس برنامهٔ ثبت‌شده است، نه تأیید زنده.</p></div></article>`}
function renderDetail(){let p=state.selected,sort=$('#shopSort')?.value||'balanced';$('#detail').innerHTML=`<button class="back" id="backCatalog">→ بازگشت به نتایج</button><div class="detail-top"><div>${img(p)}</div><div><p class="small">${esc(p.category)} ${p.brand?' / '+esc(p.brand):''}</p><h2>${esc(p.title)}</h2><div class="price">از ${price(p.min)}</div><p>قیمت ثبت‌شده؛ پیش از مراجعه استعلام بگیر.</p><div class="chips">${p.specs.slice(0,5).map(x=>`<span class="chip">${esc(x.key)}: ${esc(x.value)}</span>`).join('')}</div><div class="modal-actions"><button id="shareProduct">اشتراک محصول ↗</button><button id="specsBtn" class="outline">مشخصات کامل موجود</button><button id="compareThis">⇄ افزودن به مقایسه</button><button id="editFilters">تغییر شرایط خرید</button></div></div></div><div class="shop-toolbar"><div><h2>فروشگاه‌های این محصول</h2><p class="small">رتبه‌بندی متناسب با قیمت، فاصله و زمان مراجعه · مبدأ: ${esc(state.point.label)}</p></div><select id="shopSort" aria-label="ترتیب فروشگاه‌ها"><option value="balanced">پیشنهاد متعادل</option><option value="price">ارزان‌ترین قیمت</option><option value="distance">نزدیک‌ترین فروشگاه</option></select></div><div id="shopList"></div>`;$('#shopSort').value=sort;renderShops();$('#shopSort').onchange=renderShops;$('#backCatalog').onclick=showCatalog;$('#editFilters').onclick=()=>{showCatalog();$('.filters').classList.add('is-open');$('#mobileFilters').setAttribute('aria-expanded','true');$('.filters').scrollIntoView({behavior:'smooth'})};$('#specsBtn').onclick=()=>modal(`<h2>مشخصات محصول</h2><p>${esc(p.title)}</p>${p.specs.length?`<div class="compare-table"><table>${p.specs.map(x=>`<tr><th>${esc(x.key)}</th><td>${esc(x.value)}</td></tr>`).join('')}</table></div>`:'<p>مشخصاتی در داده‌های این محصول ثبت نشده است.</p>'}`);$('#compareThis').onclick=()=>toggleCompare(p.id,true)}
function renderShops(){const os=ranked(state.selected);$('#shopList').innerHTML=os.length?os.map(shopCard).join(''):'<div class="empty"><b>فروشگاه منطبق باقی نمانده است</b><p>فیلترها را تغییر بده یا مدل مشابه انتخاب کن.</p><button id="similar">مدل‌های مشابه</button><button id="clearExclusions">برگرداندن فروشگاه‌های کنارگذاشته‌شده</button></div>';if($('#similar'))$('#similar').onclick=()=>{let q=state.selected.category;$('#query').value=q;search(q)};if($('#clearExclusions'))$('#clearExclusions').onclick=()=>{state.excluded.clear();renderShops()}}
function toggleCompare(id,on){let p=state.products.find(x=>x.id===id)||state.selected;if(on){if(!state.compare.some(x=>x.id===id)){if(state.compare.length>=3){toast('برای مقایسهٔ خوانا، حداکثر ۳ محصول انتخاب کن.');render();return}state.compare.push(p);toast('به مقایسه اضافه شد')}}else state.compare=state.compare.filter(x=>x.id!==id);$('#compareCount').textContent=fa(state.compare.length);companion?.refresh()}
$('#compareBtn').onclick=()=>{let ps=state.compare;if(ps.length<2){toast('حداقل دو محصول را برای مقایسه انتخاب کن.');return}let keys=[...new Set(ps.flatMap(p=>p.specs.map(s=>s.key)))].slice(0,15);modal(`<h2>مقایسهٔ گزینه‌های شما</h2><p>قیمت، مشخصات و فروشنده‌ها؛ انتخاب نهایی با شماست.</p><div class="compare-table"><table><tr><th>محصول</th>${ps.map(p=>`<td>${img(p)}<p>${esc(p.title)}</p><button data-product="${p.id}">انتخاب این مدل</button></td>`).join('')}</tr><tr><th>شروع قیمت ثبت‌شده</th>${ps.map(p=>`<td>${price(p.min)}</td>`).join('')}</tr><tr><th>تعداد پیشنهاد فروش</th>${ps.map(p=>`<td>${fa(new Set(p.offers.map(o=>o.shop)).size)}</td>`).join('')}</tr>${keys.map(k=>`<tr><th>${esc(k)}</th>${ps.map(p=>`<td>${esc(p.specs.find(x=>x.key===k)?.value||'نامشخص')}</td>`).join('')}</tr>`).join('')}</table></div><p class="small">تفاوت نام و دسته‌بندی، به‌تنهایی به معنی برتری کیفیت نیست.</p>`)};
function verification(id){const p=state.selected,s=shops[id],o=p.offers.find(x=>x.shop===id);modal(`<h2>پیش از حرکت، استعلام بگیر</h2><p>${esc(s.name)} · ${esc(p.title)}</p><div class="modal-note">شماره‌های دیتاست ساختگی‌اند؛ تماس خودکار غیرفعال است. هیچ تماس یا تأیید موجودی واقعی انجام نشده است. برای اتصال سرویس تماس، شمارهٔ معتبر و دسترسی سرویس لازم است.</div><h3>متن آمادهٔ پرسش از فروشگاه</h3><textarea id="callScript" readonly>سلام، برای خرید حضوری ${esc(p.title)} تماس گرفتم. قیمت ثبت‌شده ${fa(o.price||0)} تومان است. قیمت امروز و موجودی مدل دقیق را تأیید می‌کنید؟ رنگ، سایز یا گارانتی آن چیست؟ تا چه ساعتی باز هستید؟ آدرس دقیق طبقه، واحد و ورودی کجاست؟ آیا پرداخت اعتباری حضوری دارید و با چه شرایطی؟</textarea><div class="modal-actions"><button id="copyScript">کپی متن</button>${s.website_url&&/^https?:\/\//.test(s.website_url)?`<a href="${esc(s.website_url)}" target="_blank" rel="noopener" class="chip">وب‌سایت ثبت‌شده ↗</a>`:''}</div><label>نتیجهٔ پیگیری شما<textarea id="noteText" placeholder="مثلاً: پاسخ نداد، یا قیمت جدید و زمان مراجعه…"></textarea></label><p class="small">یادداشت شخصی در همین مرورگر ذخیره می‌شود و تأیید رسمی فروشگاه نیست.</p><div class="modal-actions"><button id="saveNote" class="primary">ذخیرهٔ نتیجهٔ پیگیری</button><button id="noAnswer">پاسخ نداد؛ جایگزین بده</button></div>`);$('#copyScript').onclick=async()=>{try{await navigator.clipboard.writeText($('#callScript').value);toast('متن کپی شد.')}catch{toast('متن را انتخاب و کپی کن.')}};$('#saveNote').onclick=()=>{let t=$('#noteText').value.trim();if(!t)return toast('نتیجهٔ پیگیری را بنویس.');state.notes[p.id+id]={text:t,at:new Date().toISOString()};storage.set('notes',state.notes);close();renderShops();$('#step3').classList.add('active')};$('#noAnswer').onclick=()=>fail(id)}
function fail(id){state.excluded.add(id);close();renderShops();toast('این فروشگاه از پیشنهادها کنار رفت؛ گزینهٔ بعدی بر اساس شرایط شما مرتب شد.');$('#shopList').scrollIntoView({behavior:'smooth'})}
function address(id){const s=shops[id],a=s.address||'',floor=a.match(/طبقه[^،,]{0,35}/)?.[0],unit=a.match(/واحد[^،,]{0,25}/)?.[0];modal(`<h2>تا درِ فروشگاه</h2><h3>${esc(s.name)}</h3><p>${esc(a||'آدرس ثبت نشده')}</p><div class="chips"><span class="chip">${esc(floor||'طبقه نامشخص')}</span><span class="chip">${esc(unit||'واحد نامشخص')}</span></div><div class="modal-note">طبقه و واحد از آدرس دیتاست استخراج شده‌اند. در صورت نامشخص بودن، از فروشنده بپرس. نام بیشتر فروشگاه‌ها ساختگی است؛ جستجو با آدرس انجام می‌شود.</div><div class="modal-actions"><a class="chip" target="_blank" rel="noopener" href="https://www.google.com/search?q=${encodeURIComponent(a+' آدرس پاساژ طبقه واحد')}">بررسی آدرس در گوگل ↗</a><a class="chip" target="_blank" rel="noopener" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(s.lat&&s.lon?s.lat+','+s.lon:a)}">مشاهده روی نقشه ↗</a></div>`)}
function savePlan(id){const p=state.selected;if(state.plan.some(x=>x.product===p.id&&x.shop===id))return toast('این گزینه در برنامهٔ خرید هست.');state.plan.push({product:p.id,title:p.title,shop:id,at:new Date().toISOString()});storage.set('plan',state.plan);companion?.refresh();toast('در برنامهٔ خرید ذخیره شد.');$('#step3').classList.add('active')}
function plan(){modal(`<h2>برنامهٔ خرید من</h2><p>گزینه‌های اصلی و جایگزین را برای مراجعه نگه دار.</p>${state.plan.length?state.plan.map((x,i)=>{let s=shops[x.shop];return `<article class="plan-item"><h3>${esc(x.title)}</h3><p>${esc(s?.name)} · ${esc(s?.address)}</p><p class="small">${esc(hours(s).text)} · موجودی تأیید نشده</p><div class="modal-actions"><button data-product="${x.product}">بازگشت به مقایسهٔ فروشگاه‌ها</button><button data-remove="${i}">حذف از برنامه</button></div></article>`}).join(''):'<div class="empty">هنوز گزینه‌ای ذخیره نکرده‌ای.<p>در صفحهٔ محصول، فروشگاه مناسب را در برنامه ذخیره کن.</p></div>'}<div class="modal-note">پیش از رفتن: مدل دقیق، قیمت، موجودی، ساعت مراجعه، طبقه و واحد و شرایط پرداخت را بررسی کن.</div>${state.plan.length?'<button id="exportPlan" class="outline">دریافت برنامهٔ خرید</button>':''}`);if($('#exportPlan'))$('#exportPlan').onclick=()=>{let text=state.plan.map(x=>{let s=shops[x.shop];return x.title+'\n'+s.name+'\n'+s.address+'\n'+hours(s).text+'\nموجودی تأیید نشده'}).join('\n\n');const a=document.createElement('a'),url=URL.createObjectURL(new Blob(['\ufeff'+text],{type:'text/plain;charset=utf-8'}));a.href=url;a.download='برنامه-خرید.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}}
function locationModal(){modal(`<h2>از کجا به خرید می‌روی؟</h2><p>فاصله‌ها بر اساس این نقطه محاسبه می‌شوند؛ فاصلهٔ مستقیم‌اند، نه زمان مسیریابی.</p><div class="choices">${[['مرکز شهر',35.7007,51.4091],['تجریش',35.804,51.4305],['صادقیه',35.721,51.3357],['ونک',35.757,51.409],['تهرانپارس',35.733,51.530]].map(x=>`<button data-point="${x[1]},${x[2]},${x[0]}">${x[0]}</button>`).join('')}</div><button id="gps" class="outline">⌖ استفاده از موقعیت فعلی من</button><p class="small">فقط با اجازهٔ مرورگر؛ موقعیت برای محاسبه در همین دستگاه نگه داشته می‌شود.</p><label>عرض جغرافیایی<input id="lat" type="number" step="any" value="${state.point.lat}"></label><label>طول جغرافیایی<input id="lon" type="number" step="any" value="${state.point.lon}"></label><button id="savePoint" class="primary">ثبت نقطهٔ دلخواه</button>`);$('#savePoint').onclick=()=>setPoint(+$('#lat').value,+$('#lon').value,'نقطهٔ انتخابی');$('#gps').onclick=()=>{if(!navigator.geolocation)return toast('موقعیت‌یابی در این مرورگر پشتیبانی نمی‌شود.');navigator.geolocation.getCurrentPosition(p=>setPoint(p.coords.latitude,p.coords.longitude,'موقعیت من'),()=>toast('موقعیت در دسترس نیست؛ یک محله انتخاب کن.'),{timeout:10000})}}
function setPoint(lat,lon,label){if(!Number.isFinite(lat)||!Number.isFinite(lon)||Math.abs(lat)>90||Math.abs(lon)>180)return toast('مختصات معتبر وارد کن.');state.point={lat,lon,label};storage.set('point',state.point);$('#location span').textContent=label;close();render();if(state.selected&&!$('#detail').hidden)renderDetail()}
function guideModal(step=1){if(step===1){modal(`<h2>برای چه چیزی راهنمایی می‌خواهی؟</h2><p>۱ از ۲ · اول نیازت را مشخص کنیم.</p><div class="choices">${['کفش','گوشی موبایل','لپ تاپ','هدفون','ساعت','جاروبرقی'].map(c=>`<button data-gcat="${c}" class="${guide.category===c?'selected':''}">${c}</button>`).join('')}</div><label>یا دستهٔ دیگری بنویس<input id="customCategory" placeholder="مثلاً دوربین" value="${esc(guide.category)}"></label><button id="guideNext" class="primary">ادامه ←</button>`);$('#guideNext').onclick=()=>{guide.category=$('#customCategory').value.trim()||'کفش';guideModal(2)}}else{modal(`<h2>چه چیزی برایت مهم‌تر است؟</h2><p>۲ از ۲ · ${esc(guide.category)}</p><div class="choices">${['روزمره','ورزشی','کار و تحصیل','اقتصادی','کیفیت و امکانات'].map(c=>`<button data-guse="${c}" class="${guide.use===c?'selected':''}">${c}</button>`).join('')}</div><label>حداکثر بودجه (تومان)<input id="guideBudget" type="number" min="0" placeholder="مثلاً ۵۰۰۰۰۰۰" value="${esc(guide.budget)}"></label><p class="modal-note">راهنما بر اساس دسته، واژه‌های کاربرد و بودجه جستجو می‌کند؛ کیفیت یا تناسب پزشکی محصول را از روی نام حدس نمی‌زند. برای انتخاب نهایی، مشخصات گزینه‌ها را مقایسه کن.</p><div class="modal-actions"><button id="guideResults" class="primary">پیدا کردن گزینه‌های مناسب</button><button id="guideBack">مرحلهٔ قبل</button></div>`);$('#guideBack').onclick=()=>guideModal(1);$('#guideResults').onclick=async()=>{guide.budget=$('#guideBudget').value;$('#budget').value=guide.budget;let q=guide.category;if(q==='کفش'&&guide.use==='ورزشی')q='کفش ورزشی';if(q==='لپ تاپ')q='لپ';$('#query').value=q;if(guide.use==='اقتصادی')$('#productSort').value='cheap';close();await search(q);toast('گزینه‌ها با دسته و بودجهٔ شما پیدا شدند؛ دو مدل را برای مقایسه انتخاب کن.')}}}
function reset(){for(let s of ['#budget','#visitTime'])$(s).value='';$('#radius').value='100';$('#credit').checked=false;$('#openOnly').checked=false;state.excluded.clear();search($('#query').value.trim())}
document.addEventListener('click',e=>{const el=e.target.closest('button,a');if(!el)return;if(el.dataset.query!==undefined){$('#query').value=el.dataset.query;search(el.dataset.query)}if(el.dataset.product){close();openProduct(el.dataset.product)}if(el.dataset.verify)verification(el.dataset.verify);if(el.dataset.address)address(el.dataset.address);if(el.dataset.save)savePlan(el.dataset.save);if(el.dataset.fail)fail(el.dataset.fail);if(el.hasAttribute('data-reset'))reset();if(el.dataset.point){let [a,b,c]=el.dataset.point.split(',');setPoint(+a,+b,c)}if(el.dataset.gcat){guide.category=el.dataset.gcat;guideModal(1)}if(el.dataset.guse){guide.budget=$('#guideBudget').value;guide.use=el.dataset.guse;guideModal(2)}if(el.dataset.remove!==undefined){state.plan.splice(+el.dataset.remove,1);storage.set('plan',state.plan);companion?.refresh();plan()}});
document.addEventListener('change',e=>{if(e.target.dataset.compare)toggleCompare(e.target.dataset.compare,e.target.checked)});
$('#searchForm').onsubmit=e=>{e.preventDefault();search($('#query').value.trim())};$('#apply').onclick=()=>{search($('#query').value.trim());if(matchMedia('(max-width:800px)').matches){$('.filters').classList.remove('is-open');$('#mobileFilters').setAttribute('aria-expanded','false')}toast('فیلترها اعمال شد.')};$('#reset').onclick=reset;$('#productSort').onchange=()=>state.query?search(state.query):render();$('#more').onclick=()=>{state.shown+=24;render()};$('#location').onclick=locationModal;$('#savedTop').onclick=plan;$('#mobileSaved').onclick=plan;$('#startGuide').onclick=()=>guideModal();$('#guideAgain').onclick=()=>guideModal();$('.brand').onclick=e=>{e.preventDefault();showCatalog();window.scrollTo({top:0,behavior:'smooth'})};$('#theme').onclick=()=>{document.body.classList.toggle('dark');const dark=document.body.classList.contains('dark');storage.set('dark',dark);$('#theme').setAttribute('aria-pressed',String(dark))};if(storage.get('dark',false)){document.body.classList.add('dark');$('#theme').setAttribute('aria-pressed','true')}
$('#allCats').onclick=()=>modal(`<h2>دسته‌بندی‌های دیتاست</h2><p>یک دسته را برای جستجو انتخاب کن.</p><div class="choices">${(meta.categories||[]).slice(0,150).map(x=>`<button data-query="${esc(x[0])}" onclick="document.querySelector('#modal').close()">${esc(x[0])} <small>(${fa(x[1])})</small></button>`).join('')}</div>`);
$('#about').onclick=()=>modal(`<h2>شفافیت اطلاعات</h2><p>این پروژه نمونهٔ مستقل چالش ترب است.</p><div class="modal-note">${fa(meta.products)} محصول، ${fa(meta.offers)} پیشنهاد و ${fa(meta.shops)} فروشگاه از دیتاست رسمی v16.</div><p>قیمت‌ها ثبت‌شده‌اند و موجودی زنده نیست. تمام شماره‌ها و بیشتر نام‌ها ساختگی‌اند. تماس واقعی، تأیید خودکار و جستجوی خودکار گوگل در این نسخه متصل نیستند. پیگیری شما با برچسب یادداشت شخصی ذخیره می‌شود.</p><p>پیشنهاد متعادل: ۴۵٪ نسبت قیمت به کمینه، ۳۵٪ فاصلهٔ مستقیم، ۲۰٪ سازگاری با ساعت مراجعه. فیلتر اعتبار فقط اطلاعات حضوری صریح را می‌پذیرد. برنامهٔ خرید و موقعیت در مرورگر نگه داشته می‌شوند؛ پیام گفتگو در حالت اتصال مدل به سرور ارسال می‌شود. پیوندهای نقشه و گوگل هنگام باز کردن، مقصد را به همان سرویس می‌فرستند.</p>`);
$('#mobileFilters').onclick=()=>{const open=$('.filters').classList.toggle('is-open');$('#mobileFilters').setAttribute('aria-expanded',String(open));if(open)$('.filters').scrollIntoView({behavior:'smooth',block:'nearest'})};
$('#askAdvisor').onclick=()=>{modal(`<h2>دربارهٔ انتخابت بپرس</h2><p>نیازت چیست و بین چه گزینه‌هایی مرددی؟</p><label>دسته یا عبارت جستجو<input id="advisorQuery" value="${esc(state.query||'کتانی')}"></label><label>پیام شما<textarea id="advisorMessage" placeholder="مثلاً برای استفاده روزمره، راحتی و دوام برایم مهم‌تر است."></textarea></label><p class="small">در حالت متصل به مدل، پیام و گزینه‌های بازیابی‌شده به ارائه‌دهندهٔ سرویس ارسال می‌شود. نسخهٔ static راهنمای ساختاریافته ارائه می‌دهد.</p><button id="advisorSend" class="primary">بررسی گزینه‌ها</button><div id="advisorAnswer" class="modal-note" hidden></div><button id="advisorResults" class="outline" hidden>دیدن و مقایسهٔ محصولات</button>`);$('#advisorSend').onclick=async()=>{let message=$('#advisorMessage').value.trim(),q=$('#advisorQuery').value.trim();if(!message||!q)return toast('دسته و نیازت را بنویس.');$('#advisorSend').disabled=true;const box=$('#advisorAnswer');box.hidden=false;box.textContent='در حال بررسی…';try{const r=await fetch('/api/assistant',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message,query:q,budget:parseAmount($('#budget').value)||0}),signal:AbortSignal.timeout(40000)});if(!r.ok)throw Error();const j=await r.json();box.textContent=(j.mode==='model'?'پاسخ مدل: ':'راهنمای ساختاریافته: ')+j.message}catch{box.textContent='راهنمای ساختاریافته: برای '+q+'، بودجه، ویژگی اصلی و شرایط استفاده را مشخص کن. دو یا سه مدل را با مشخصات واقعی مقایسه کن. سرویس مدل زبانی در این نسخه متصل نیست؛ موجودی و کیفیت از روی نام محصول قابل تأیید نیست.'}finally{if($('#advisorSend'))$('#advisorSend').disabled=false;if($('#advisorResults')){$('#advisorResults').hidden=false;$('#advisorResults').onclick=()=>{close();$('#query').value=q;search(q)}}}}};
async function init(){$('#status').textContent='در حال دریافت داده‌ها…';try{[shops,meta,state.products]=await Promise.all([json('data/shops.json'),json('data/meta.json'),json('data/featured.json')]);companion=initCompanion({state,storage,$,esc,fa,icon,modal,toast,openProduct,search,toggleCompare,meta});$('#location span').textContent=state.point.label;$('#dataInfo').textContent=`${fa(meta.products)} محصول · ${fa(meta.offers)} پیشنهاد · ${fa(meta.shops)} فروشگاه، نسخهٔ ۱۶؛ دادهٔ غیرزنده.`;render();$('#status').textContent='قیمت ثبت‌شده · موجودی پیش از مراجعه استعلام شود';
const params=new URLSearchParams(location.search),initialProduct=params.get('product'),initialQuery=params.get('q');
if(params.has('budget'))$('#budget').value=parseAmount(params.get('budget'));
if(companion.restoreIds.length){const idx=await loadIndex();const restored=await Promise.all(companion.restoreIds.map(async id=>{const row=idx.find(x=>x[0]===id);return row?hydrate(row):null}));state.compare=restored.filter(Boolean);companion.refresh()}
if(initialQuery)await search(initialQuery);if(initialProduct)await openProduct(initialProduct)}catch{$('#status').textContent='بارگیری داده‌ها ناموفق بود؛ صفحه را دوباره بارگذاری کن.'}}
init();
